 'ideal' => [95=>'mirrors you', 85=>'is related to you', 78=>'complements you', 60=>'is neutral to you', 45=>'challenges you'],
 'life' => [
  1=>'Your life path is 1, and 1 belongs to beginnings: the will to stand on your own feet and go first. Taking initiative often comes easier to you than waiting for others. In love and friendship you need people who respect your independence – and who can live with you sometimes deciding before you have asked. Your challenge is to give the other person room beside you, not behind you.',
  2=>'Your life path is 2, the number of relationship, sensitivity and cooperation. You sense moods before anyone says them out loud, and you are often the one who brings calm and builds bridges. In close relationships you give closeness and loyalty. Just take care not to adapt so much that you lose your own voice – it is needed too.',
  3=>'Your life path is 3, the number of expression and creative joy. You live through words, humour, ideas and meeting people, and you can make a whole room relax. You need joy and play, and people who let you be seen. Your challenge is to stay in the depths when things get serious, rather than dancing lightly across them.',
  4=>'Your life path is 4, the number of foundations. You build what is meant to last, and the people around you know that a yes from you means something. You show care through action: you turn up, sort things out and hold on. Make sure security does not become control – a mature 4 can change course without losing the foundation.',
  5=>'Your life path is 5, the number of freedom and change. You need movement, new impressions and the feeling that life is open. You flourish with people who join the adventure rather than hold you back. Your challenge is to tell freedom that helps you grow from restlessness that only scatters your energy – and to stay when life becomes everyday.',
  6=>'Your life path is 6, the number of care, home and responsibility. You often feel responsible for the wellbeing of the people around you, and you can create a warm home. You give a lot. Practise receiving too – and let the other person carry their own responsibilities, so care does not become carrying everything.',
  7=>'Your life path is 7, the number of depth. You look for the meaning behind what happens, and you need time alone to feel what you really think. You open up slowly, but deeply. The right people understand that your silence is not rejection – and you, for your part, can practise letting them in before every thought is finished.',
  8=>'Your life path is 8, the number of drive, resources and results. You see what needs doing and have the strength to do it. You want relationships between equals – people who can handle your strength and have their own. Your challenge is to keep work, money and control in proportion to the softer side of life.',
  9=>'Your life path is 9, the last of the root numbers, and it carries a little of all the others. You are generous, idealistic and tend to see the bigger picture. You are romantic and compassionate. Your challenge is to look after yourself as well as you look after others – and to let go of what is over, so the new has room.'],
 'master' => [
  11=>'Because your life path is the master number 11, the 2 is read in a more intense form: strong intuition, inspiration and fine antennae for what is left unsaid. It can make you extra sensitive to unrest around you, but also someone who lifts others simply by being there.',
  22=>'Because your life path is the master number 22, the 4 is read on a larger scale: the ability to make big visions concrete. You may demand a lot of yourself. Remember that even the greatest builder needs rest.',
  33=>'Because your life path is the master number 33, the 6 is read in its most loving form: the guide who carries and lifts others. The gift is great, and that is exactly why you need someone who carries you too.'],
 'soul' => [1=>'to be seen for who you are and to have room to choose for yourself. You grow restless when someone tries to decide for you.', 2=>'closeness, tenderness and someone who truly listens. Small signs of care often mean more to you than grand gestures.', 3=>'joy, play and someone who laughs with you. You need to say what you think without everything being taken so seriously.', 4=>'predictability and a relationship you can trust completely. Kept promises are love in your language.', 5=>'freedom, variety and people who do not tie you down. You are most faithful when you do not feel trapped.', 6=>'a safe home and the feeling of belonging. You need to give care – and, just as important, to receive it.', 7=>'time to yourself, conversations with depth and respect for your thoughts. Shallow small talk drains you more than you show.', 8=>'equality – people who respect your ambitions and stand firmly on their own feet.', 9=>'meaning and generosity. You need relationships with room for the world outside the two of you.'],
 'expr' => [1=>'direct, brave and clear. People quickly sense where you stand.', 2=>'attentive, gentle and cooperative. Many people feel safe around you.', 3=>'charming, creative and talkative. You get noticed, often without trying.', 4=>'reliable, thorough and calm. You give the impression that things are taken care of.', 5=>'curious, funny and full of life – sometimes a little restless.', 6=>'warm, responsible and protective. People come to you when they need someone.', 7=>'enigmatic, wise and thoughtful. It takes time to get to know you, and it is worth the time.', 8=>'confident, efficient and charismatic. You fill the room when you want to.', 9=>'generous, romantic and broad-minded. You make people feel understood.'],
 'mat' => [1=>'greater independence and the courage to stand by your choices', 2=>'deeper partnership and inner balance', 3=>'creative joy and a freer expression', 4=>'a security you have built yourself', 5=>'freedom and a life in many colours', 6=>'family, community and care', 7=>'wisdom and inner calm', 8=>'influence and lasting security', 9=>'generosity, forgiveness and wholeness'],
 'question' => [1=>'Where in your life are you waiting for someone else to take the first step – and what happens if you take it yourself?', 2=>'When did you last say clearly what you need, not only what the other person needs?', 3=>'Who in your life gets to see you when you are not being funny?', 4=>'What could you loosen your grip on without the foundation giving way?', 5=>'Which freedom helps you grow – and which is really an escape?', 6=>'Who looks after you when you have looked after everyone else?', 7=>'What would happen if you shared a thought before it was finished?', 8=>'What is success to you when no one else is watching?', 9=>'What are you ready to let go of, so something new can come in?'],
 'year' => [
  1=>'This year asks for initiative. What has been unclear can find direction when you take the first step yourself. New projects, roles or a new way of standing in your own life may matter, but the strength lies in choosing consciously rather than rushing.',
  2=>'This year works more quietly. Relationships, cooperation, timing and sensitivity matter more than forcing quick results. You move further by listening carefully, allowing things to mature and using diplomacy without surrendering your own direction.',
  3=>'This is a year of expression, contact and creative energy. Words, ideas and people can open doors, and it becomes easier to show more of who you are. The challenge is to gather your energy well enough for inspiration to become something finished.',
  4=>'This year asks you to build. Work, details, finances, routines and practical commitments may demand more, but this is exactly where a lasting foundation can be created. Patience and order will give more than shortcuts.',
  5=>'This is a mobile year. Changes, new contacts, travel or unexpected turns can make life less predictable. Flexibility is a strength now; the task is to distinguish freedom that develops you from restlessness that only scatters your energy.',
  6=>'This year draws attention to the people you are responsible for and the life you build together. Family, home, love and duties may move closer. You can do much for others, but care must not turn into carrying everything yourself.',
  7=>'This is a year of depth. The need for quiet, knowledge and greater understanding may be stronger than the need for outer speed. Study, reflection and specialization are supported; constant pursuit of visible results can feel empty.',
  8=>'This is a year when work, responsibility, money and results become visible. Earlier effort can produce returns, while weak structures become harder to ignore. Ambition is useful, but power and money need to stay in proportion to the rest of life.',
  9=>'This year completes a nine-year rhythm. Something is ready to be completed, understood or released before the next direction becomes clear. Feelings may sit closer to the surface, but there can also be relief in making room for what comes next.'],
 'about' => ['The vowels in your name give the number {soul}, what lies innermost. It says that in close relationships you need {soultext} Your name number is {expr}, and this is how others meet you: as {exprtext}', 'Your maturity number {mat} shows the direction life gradually takes you, often most clearly from your mid-thirties: towards {mattext}.', 'In {y} you are in personal year {py}. {yeartext}'],
 'o_life' => [
  1=>'{navn} has life path 1 – someone who takes initiative and prefers their own path. With {navn} you get a partner or friend with direction and courage. Give {them} room to decide, and you will get loyalty back.',
  2=>'{navn} has life path 2 – a sensitive bridge-builder who picks up moods quickly. {navn} gives closeness and loyalty, and needs you to be both clear and gentle.',
  3=>'{navn} has life path 3 – playful, expressive and social. Life with {them} is rarely dull. {navn} needs to be seen and heard, and someone who also dares to go into the depths.',
  4=>'{navn} has life path 4 – down to earth, loyal and building to last. {navn} shows care through action. Keep your promises and trust grows quickly.',
  5=>'{navn} has life path 5 – free, curious and always on the way somewhere. With {them}, life becomes movement. Do not try to hold {them} back; invite {them} along instead.',
  6=>'{navn} has life path 6 – caring and home-loving, with a big sense of responsibility. {navn} gives a lot. Show that you can take care of {them} too.',
  7=>'{navn} has life path 7 – reflective, searching and fond of quiet. {navn} opens up slowly, but deeply. Give {them} time, and ask questions that go beneath the surface.',
  8=>'{navn} has life path 8 – focused and decisive. {navn} wants an equal, not a spectator. Respect {their} ambitions, and feel free to show your own.',
  9=>'{navn} has life path 9 – generous, romantic and idealistic. {navn} sees the bigger picture and cares about many. Help {them} take care of {their} own needs as well.'],
 'o_soul' => [1=>'to be seen for who they are and to choose for themselves', 2=>'closeness, tenderness and someone who listens', 3=>'joy, play and someone to laugh with', 4=>'predictability and relationships to rely on', 5=>'freedom and someone who joins the adventure', 6=>'a safe home – and care in return', 7=>'time alone and conversations with depth', 8=>'people who stand firmly on their own feet', 9=>'meaning, and relationships with room for the world'],
 'o_expr' => [1=>'direct, brave and clear', 2=>'attentive, gentle and cooperative', 3=>'charming, creative and talkative', 4=>'reliable, thorough and calm', 5=>'curious, funny and full of life', 6=>'warm, responsible and protective', 7=>'enigmatic, wise and thoughtful', 8=>'confident, efficient and charismatic', 9=>'generous, romantic and broad-minded'],
 'o_about' => '{life} Deep down, {navn} needs {soul}. You will probably experience {them} as {expr}.',
 'y_you' => [1=>'you feel more like starting something new and deciding for yourself', 2=>'you become more sensitive and seek closeness and cooperation', 3=>'you want to get out, express yourself and meet people', 4=>'you are focused on building, organising and getting things in place', 5=>'you need movement, change and air', 6=>'home, responsibility and close relationships pull at you', 7=>'you turn a little inward and need quiet to think', 8=>'work, money and results take up a lot of space', 9=>'you are closing a chapter and making room for something new'],
 'y_other' => [1=>'{navn} wants to start something new and make {their} own choices', 2=>'{navn} softens and seeks closeness', 3=>'{navn} wants to get out, share {their} ideas and be social', 4=>'{navn} is building, organising and making plans', 5=>'{navn} needs change and freedom', 6=>'home and responsibility fill much of {their} year', 7=>'{navn} turns inward and needs quiet', 8=>'{navn} is focused on work and results', 9=>'{navn} is finishing something and getting ready for what comes next'],
 'y_pair' => 'You are in a {a} year: {you}. {navn} is in a {b} year: {other}. {link}',
 'y_link' => [
  95=>['You share the same vibration at the same time, and understanding each other can feel unusually easy. Use the tailwind for something you build together – but take care not to reinforce the same blind spots.', 'When two people share a personal year, they often go through the same questions at the same time. Talk about them out loud; that is where closeness grows.', 'Same number, same theme. It brings calm and recognition, but also a temptation to take each other for granted. Say what you see in the other person.', 'You are in step this year. It is a gift – and an invitation to ask: what do we want to use this harmony for?', 'When both feel the same, it is easy to confirm each other. Dare to disagree too; it keeps the harmony alive.'],
  85=>['Your years belong to the same number family. You show it differently, but you are driven by something related, which makes it easier to give each other room without losing contact.', 'These are related years. One of you shows it clearly, the other more quietly – but you pull in the same direction. A good year for a shared plan.', 'There is a natural kinship between your years. You will often notice that the other understands without long explanations.', 'You speak the same language this year, just with different accents. Listen for what the other person really means.', 'Related years often bring a quiet understanding. Use it to make a decision you have been putting off.'],
  78=>['Your years complement each other: what one lacks right now, the other has more of. It becomes a good year if you let each other contribute what you do best.', 'A complementary combination. Do not try to become alike – let the difference do the work, and thank each other for what the other carries.', 'You pull in slightly different directions, but in a way that balances. One brings speed, the other brings grounding.', 'Where one is strong, the other can rest. Say out loud what you appreciate in the other person this year.', 'This is a year when you can learn from each other. What can you take from the other person\'s theme?'],
  60=>['Your years stand side by side without pulling especially together or apart. That gives freedom, but also a responsibility to create the shared part yourselves.', 'No strong tailwind and no headwind. Closeness comes from what you choose to do together, not from the numbers alone.', 'A neutral year between you. Ask each other often: what do you need from me right now?', 'The numbers leave you alone this year. That means you are the ones who set the mood.', 'A year when each of you has your own things. Agree on a regular time that is only yours, so you do not drift past each other.'],
  45=>['Your tempos may pull in different directions here. It does not have to become conflict, but it requires you to say clearly what you need – before irritation says it for you.', 'Numerology calls this a friction pair. Friction is not a mistake; it is often where you learn the most about each other. Agree early on how you can take breaks without withdrawing.', 'A year that tests patience. What irritates you in the other may show you something you need more or less of yourself.', 'Different tempos this year: one wants to go one way, the other another. Ask "what do you need?" rather than "why do you do that?".', 'Friction can become warmth if you use it well. Be generous with each other in the periods when things grate.']],
 'rel' => [
  1=>'Shared number 1 gives a pair who start things together. You can become an engine for each other – new projects, new places, new chapters. The task is to make it a shared initiative, not two parallel ones.',
  2=>'Shared number 2 is the number of partnership itself. The strength lies in the quiet interplay: listening, waiting and finding solutions together. Take care not to avoid disagreement for so long that the unsaid grows heavy.',
  3=>'Shared number 3 gives a playful, social pair. Humour, creativity and friends around you are the glue. Remember to talk about what is difficult too – not only what is fun.',
  4=>'Shared number 4 builds: home, routines and loyalty that lasts. Such a bond often grows stronger year by year, as long as structure does not smother spontaneity.',
  5=>'Shared number 5 gives an adventurous pair: travel, change and freedom. It is lively – and requires you to agree on what feels safe, so freedom does not turn into distance.',
  6=>'Shared number 6 is about home, care and responsibility – a bond others like to gather around. Share the responsibility, so neither of you ends up carrying everything.',
  7=>'Shared number 7 is the number of kindred spirits: depth, conversation and respect for each other\'s space. You do not always have to be together to be close.',
  8=>'Shared number 8 gives a power pair with shared goals and things you achieve together. Remember the bond is not a project to deliver – it is also meant to be lived.',
  9=>'Shared number 9 gives a generous, idealistic bond that wants something bigger than itself. You can mean a lot to others. Look after what the two of you have, too.'],
 'chat' => ['Hi, lovely that you wrote! I saw our shared number is {rel} – {theme}. Do you recognise that?', 'My life path is {lp}, and honestly I need {soul}. What matters most to you?', 'The engine says {pct} %, but I am more curious about you beyond the numbers. What do you like to do on a Sunday?', 'Right now I am in a {py} year, and I can feel it: {year}. How is your year going?', 'According to the numbers, {month} is our strongest month. Shall we plan something then? 😊', 'I read that life path {olp} is {type}. Is that true for you?', 'This was nice. Coffee in {city} some day?'],
 'c_soul' => [1=>'room to be myself', 2=>'closeness and someone who listens', 3=>'someone to laugh with', 4=>'someone I can fully trust', 5=>'freedom and a bit of adventure', 6=>'to belong somewhere', 7=>'time to myself and real conversations', 8=>'equality', 9=>'for what we share to mean something'],
 'c_year' => [1=>'I feel like starting something new', 2=>'everything moves a bit slower and I seek more closeness', 3=>'I want to get out and meet people', 4=>'I am tidying up and building', 5=>'everything is moving', 6=>'home and the people closest to me take a lot of space', 7=>'I need more quiet than usual', 8=>'work demands a lot', 9=>'I am closing a chapter'],
],
'fa' => [
 'themes' => ['', 'ابتکار و استقلال', 'نزدیکی و همکاری', 'بیان و خلاقیت', 'امنیت و نظم', 'آزادی و تغییر', 'مراقبت و خانه', 'آرامش و عمق', 'تلاش و مسئولیت', 'همدلی و پایان یک مرحله'],
 'type' => [1=>['پیشگام', 'مستقل، شجاع، اهل رهبری'], 2=>['دیپلمات', 'گرم، شنونده، اهل همراهی'], 3=>['سخنور', 'بازیگوش، اجتماعی، خلاق'], 4=>['سازنده', 'وفادار، باثبات، عملی'], 5=>['ماجراجو', 'آزاد، خودجوش، کنجکاو'], 6=>['مراقب', 'خانه‌دوست، مسئول، مهربان'], 7=>['اندیشمند', 'عمیق، آرام، جست‌وجوگر'], 8=>['رهبر', 'جاه‌طلب، اهل عمل، سخاوتمند در ایجاد امنیت'], 9=>['آرمان‌گرا', 'همدل، رمانتیک، بلندنظر']],
 'res' => [95=>'ریشه یکسان', 85=>'خانواده عددی یکسان', 78=>'مکمل', 60=>'خنثی', 45=>'اصطکاک'],
 'comp' => ['life'=>'مسیر زندگی', 'soul'=>'نیاز درونی', 'expression'=>'بیان', 'maturity'=>'پختگی', 'timing'=>'ریتم سال'],
 'months' => ['', 'ژانویه', 'فوریه', 'مارس', 'آوریل', 'مه', 'ژوئن', 'ژوئیه', 'اوت', 'سپتامبر', 'اکتبر', 'نوامبر', 'دسامبر'],
 'label' => ['هماهنگی کمیاب', 'هم‌نوایی قوی', 'ریتم خوب', 'تضاد هیجان‌انگیز', 'ترکیب چالش‌برانگیز'],
 'ideal' => [95=>'آینه‌ی توست', 85=>'با تو هم‌خانواده است', 78=>'تو را کامل می‌کند', 60=>'نسبت به تو خنثی است', 45=>'تو را به چالش می‌کشد'],
 'life' => [
  1=>'مسیر زندگی تو ۱ است، و ۱ عدد آغاز است: اراده‌ی روی پای خود ایستادن و پیشگام بودن. معمولاً قدم اول را راحت‌تر برمی‌داری تا اینکه منتظر دیگران بمانی. در عشق و دوستی به کسانی نیاز داری که استقلالت را محترم بشمارند – و بپذیرند که گاهی پیش از پرسیدن تصمیم می‌گیری. چالش تو این است که به دیگری کنار خودت جا بدهی، نه پشت سرت.',
  2=>'مسیر زندگی تو ۲ است، عدد رابطه، حساسیت و همکاری. حال‌وهوا را پیش از آنکه کسی به زبان بیاورد حس می‌کنی و اغلب تو هستی که آرامش می‌آوری و پل می‌سازی. در رابطه‌های نزدیک، صمیمیت و وفاداری می‌بخشی. فقط مراقب باش آن‌قدر خودت را تطبیق ندهی که صدای خودت گم شود – آن صدا هم لازم است.',
  3=>'مسیر زندگی تو ۳ است، عدد بیان و شادی آفرینش. با کلمه، شوخ‌طبعی، ایده و دیدار با آدم‌ها زندگی می‌کنی و می‌توانی فضای یک جمع را باز کنی. به شادی و بازی نیاز داری و به آدم‌هایی که بگذارند دیده شوی. چالش تو این است که وقتی موضوع جدی می‌شود در عمق بمانی، نه اینکه سبک از رویش بگذری.',
  4=>'مسیر زندگی تو ۴ است، عدد پی و بنیان. چیزی را می‌سازی که باید بماند، و اطرافیانت می‌دانند «بله»ی تو معنا دارد. محبتت را با عمل نشان می‌دهی: حاضر می‌شوی، سامان می‌دهی و پایبند می‌مانی. مراقب باش امنیت به کنترل تبدیل نشود – ۴ پخته می‌تواند مسیرش را عوض کند بی‌آنکه بنیانش را از دست بدهد.',
  5=>'مسیر زندگی تو ۵ است، عدد آزادی و تغییر. به حرکت، تجربه‌های تازه و این احساس که زندگی باز است نیاز داری. کنار کسانی شکوفا می‌شوی که همراه ماجرا شوند، نه اینکه نگهت دارند. چالش تو تشخیص آزادی‌ای است که رشدت می‌دهد از بی‌قراری‌ای که فقط انرژی‌ات را پراکنده می‌کند – و ماندن، وقتی زندگی روزمره می‌شود.',
  6=>'مسیر زندگی تو ۶ است، عدد مراقبت، خانه و مسئولیت. اغلب خودت را مسئول حال خوب اطرافیانت می‌دانی و می‌توانی خانه‌ای گرم بسازی. زیاد می‌بخشی. گرفتن را هم تمرین کن – و بگذار دیگری مسئولیت خودش را به دوش بکشد تا مراقبت به بار اضافه تبدیل نشود.',
  7=>'مسیر زندگی تو ۷ است، عدد عمق. به دنبال معنای پشت اتفاق‌ها هستی و به زمانی برای تنهایی نیاز داری تا بفهمی واقعاً چه فکر می‌کنی. آرام اما عمیق باز می‌شوی. آدم‌های درست می‌فهمند سکوتت به معنای پس‌زدن نیست – و تو هم می‌توانی تمرین کنی پیش از کامل شدن هر فکر، آن‌ها را راه بدهی.',
  8=>'مسیر زندگی تو ۸ است، عدد توان، منابع و نتیجه. می‌بینی چه باید کرد و نیروی انجامش را داری. رابطه‌ی برابر می‌خواهی – کسانی که هم قدرت تو را تاب بیاورند و هم قدرت خودشان را داشته باشند. چالش تو این است که کار، پول و کنترل را در تناسب درست با بخش نرم زندگی نگه داری.',
  9=>'مسیر زندگی تو ۹ است، آخرین عدد پایه، و چیزی از همه‌ی عددهای دیگر را در خود دارد. سخاوتمند و آرمان‌گرایی و تصویر بزرگ را می‌بینی. رمانتیک و همدلی. چالش تو این است که همان‌قدر که از دیگران مراقبت می‌کنی از خودت هم مراقبت کنی – و آنچه تمام شده را رها کنی تا تازه‌ها جا پیدا کنند.'],
 'master' => [
  11=>'چون مسیر زندگی تو عدد استاد ۱۱ است، عدد ۲ در شکلی شدیدتر خوانده می‌شود: شهود قوی، الهام و حسی ظریف برای ناگفته‌ها. این می‌تواند تو را در برابر ناآرامی اطراف حساس‌تر کند، اما همچنین کسی بسازد که تنها با حضورش دیگران را بالا می‌برد.',
  22=>'چون مسیر زندگی تو عدد استاد ۲۲ است، عدد ۴ در مقیاسی بزرگ‌تر خوانده می‌شود: توانایی عملی کردن رؤیاهای بزرگ. ممکن است از خودت زیاد توقع داشته باشی. یادت باشد بزرگ‌ترین سازنده هم به استراحت نیاز دارد.',
  33=>'چون مسیر زندگی تو عدد استاد ۳۳ است، عدد ۶ در مهربان‌ترین شکلش خوانده می‌شود: راهنمایی که دیگران را حمل می‌کند و بالا می‌برد. این هدیه بزرگ است، و درست به همین دلیل به کسی نیاز داری که تو را هم حمل کند.'],
 'soul' => [1=>'دیده شدن همان‌طور که هستی و جا برای انتخاب خودت. وقتی کسی بخواهد به جایت تصمیم بگیرد بی‌قرار می‌شوی.', 2=>'نزدیکی، لطافت و کسی که واقعاً گوش بدهد. نشانه‌های کوچک محبت اغلب برایت مهم‌تر از کارهای بزرگ است.', 3=>'شادی، بازی و کسی که با تو بخندد. باید بتوانی حرفت را بزنی بی‌آنکه همه‌چیز خیلی جدی گرفته شود.', 4=>'پیش‌بینی‌پذیری و رابطه‌ای که بتوانی کاملاً به آن اعتماد کنی. قولی که نگه داشته شود، به زبان تو یعنی عشق.', 5=>'آزادی، تنوع و آدم‌هایی که تو را بند نکنند. وقتی احساس گرفتاری نکنی، وفادارترینی.', 6=>'خانه‌ای امن و احساس تعلق. نیاز داری مراقبت کنی – و به همان اندازه مهم، مراقبت دریافت کنی.', 7=>'زمانی برای خودت، گفت‌وگوهای عمیق و احترام به فکرهایت. گپ سطحی بیش از آنچه نشان می‌دهی خسته‌ات می‌کند.', 8=>'برابری – آدم‌هایی که به جاه‌طلبی‌هایت احترام بگذارند و روی پای خودشان محکم بایستند.', 9=>'معنا و سخاوت. به رابطه‌هایی نیاز داری که جایی هم برای دنیای بیرون داشته باشند.'],
 'expr' => [1=>'رک، شجاع و روشن. آدم‌ها زود می‌فهمند کجا ایستاده‌ای.', 2=>'شنونده، نرم و اهل همکاری. خیلی‌ها کنارت احساس امنیت می‌کنند.', 3=>'جذاب، خلاق و خوش‌صحبت. اغلب بی‌آنکه تلاش کنی دیده می‌شوی.', 4=>'قابل‌اعتماد، دقیق و آرام. این حس را می‌دهی که کارها در دست‌های امن است.', 5=>'کنجکاو، بامزه و سرشار از زندگی – گاهی کمی بی‌قرار.', 6=>'گرم، مسئول و حامی. آدم‌ها وقتی به کسی نیاز دارند سراغت می‌آیند.', 7=>'رازآلود، دانا و اهل تأمل. شناختنت زمان می‌برد و ارزشش را دارد.', 8=>'مطمئن، کارآمد و کاریزماتیک. هر وقت بخواهی فضا را پر می‌کنی.', 9=>'سخاوتمند، رمانتیک و بلندنظر. به آدم‌ها حس فهمیده شدن می‌دهی.'],
 'mat' => [1=>'استقلال بیشتر و شجاعت ایستادن پای انتخاب‌هایت', 2=>'همراهی عمیق‌تر و تعادل درونی', 3=>'شادی آفرینش و بیانی آزادتر', 4=>'امنیتی که خودت ساخته‌ای', 5=>'آزادی و زندگی‌ای پررنگ', 6=>'خانواده، همبستگی و مراقبت', 7=>'خرد و آرامش درونی', 8=>'اثرگذاری و امنیت پایدار', 9=>'سخاوت، بخشش و یکپارچگی'],
 'question' => [1=>'در کجای زندگی‌ات منتظری کس دیگری قدم اول را بردارد – و اگر خودت برداری چه می‌شود؟', 2=>'آخرین بار کی روشن گفتی خودت به چه نیاز داری، نه فقط دیگری؟', 3=>'چه کسی در زندگی‌ات تو را وقتی بامزه نیستی هم می‌بیند؟', 4=>'چه چیزی را می‌توانی کمی رها کنی، بی‌آنکه بنیان فرو بریزد؟', 5=>'کدام آزادی رشدت می‌دهد – و کدام در واقع فرار است؟', 6=>'وقتی از همه مراقبت کردی، چه کسی از تو مراقبت می‌کند؟', 7=>'اگر فکری را پیش از تمام شدنش با کسی در میان بگذاری، چه می‌شود؟', 8=>'وقتی هیچ‌کس نگاه نمی‌کند، موفقیت برای تو چیست؟', 9=>'آماده‌ای چه چیزی را رها کنی تا چیز تازه‌ای وارد شود؟'],
 'year' => [
  1=>'این سال از تو می‌خواهد آغازگر باشی. چیزی که مبهم بوده می‌تواند وقتی خودت قدم اول را برمی‌داری جهت روشن‌تری پیدا کند. پروژه، نقش یا شیوه تازه‌ای برای ایستادن روی پای خودت مهم می‌شود، اما قدرت اصلی در انتخاب آگاهانه است، نه در عجله.',
  2=>'این سال آرام‌تر کار می‌کند. رابطه، همکاری، زمان‌بندی و حساسیت از فشار آوردن برای نتیجه سریع مهم‌تر می‌شوند. وقتی خوب گوش می‌دهی، اجازه می‌دهی موضوع‌ها جا بیفتند و با دیپلماسی پیش می‌روی، مسیر بهتر باز می‌شود.',
  3=>'سال بیان، ارتباط و انرژی خلاق است. کلمات، ایده‌ها و آدم‌ها می‌توانند درها را باز کنند و نشان دادن بخش بیشتری از خودت آسان‌تر می‌شود. چالش این است که انرژی پراکنده نشود و الهام به نتیجه واقعی برسد.',
  4=>'این سال از تو می‌خواهد بسازی. کار، جزئیات، پول، نظم و مسئولیت‌های عملی ممکن است بیشتر شوند، اما همین‌جا فرصت ساختن پایه‌ای محکم وجود دارد. صبر و ترتیب از میانبر نتیجه بیشتری می‌دهند.',
  5=>'سال حرکت و تغییر است. آشنایی‌های تازه، سفر یا اتفاق‌های پیش‌بینی‌نشده می‌توانند برنامه‌ها را جابه‌جا کنند. انعطاف قدرت توست؛ فقط باید فرق آزادی سازنده با بی‌قراری و پراکندگی را تشخیص بدهی.',
  6=>'توجه این سال به آدم‌هایی می‌رود که نسبت به آن‌ها احساس مسئولیت داری و زندگی‌ای که با آن‌ها می‌سازی. خانواده، خانه، عشق و وظیفه پررنگ‌تر می‌شوند. مراقب باش حمایت از دیگران به به‌دوش‌کشیدن همه چیز تبدیل نشود.',
  7=>'این سال برای عمیق شدن است. نیاز به آرامش، دانش و فهم بیشتر ممکن است از سرعت بیرونی مهم‌تر شود. مطالعه، فکر و تخصص گرفتن حمایت می‌شوند. به کار درونی جا بده و از فشار بی‌وقفه برای نتیجه ظاهری کم کن.',
  8=>'در این سال کار، مسئولیت، پول و نتیجه‌ها واضح‌تر دیده می‌شوند. تلاش گذشته می‌تواند ثمر بدهد و ساختارهای ضعیف هم خودشان را نشان می‌دهند. جاه‌طلبی مفید است، اما قدرت و پول باید در تعادل با بقیه زندگی بمانند.',
  9=>'این سال یک چرخه نه‌ساله را جمع‌بندی می‌کند. چیزی باید تمام، فهمیده یا رها شود تا جهت بعدی روشن‌تر شود. احساسات نزدیک‌ترند، اما در پاک کردن فضا برای مرحله بعد سبک‌شدن هم وجود دارد.'],
 'about' => ['حروف صدادار نام تو عدد {soul} را می‌دهند، چیزی که در درونی‌ترین لایه است. این عدد می‌گوید در رابطه‌های نزدیک به این نیاز داری: {soultext} عدد نام تو {expr} است، و دیگران تو را این‌طور می‌بینند: {exprtext}', 'عدد پختگی تو {mat} جهتی را نشان می‌دهد که زندگی کم‌کم تو را به آن می‌برد، معمولاً از میانه‌ی دهه‌ی سی روشن‌تر: به سوی {mattext}.', 'در سال {y} تو در سال شخصی {py} هستی. {yeartext}'],
 'o_life' => [
  1=>'{navn} مسیر زندگی ۱ دارد – کسی که ابتکار به خرج می‌دهد و ترجیح می‌دهد راه خودش را برود. با او همراهی با جهت و شجاعت پیدا می‌کنی. به او جا بده تا خودش تصمیم بگیرد، و وفاداری‌اش را پس می‌گیری.',
  2=>'{navn} مسیر زندگی ۲ دارد – پل‌سازی حساس که حال‌وهوا را زود می‌گیرد. او نزدیکی و وفاداری می‌بخشد و نیاز دارد تو هم روشن باشی و هم ملایم.',
  3=>'{navn} مسیر زندگی ۳ دارد – بازیگوش، اهل بیان و اجتماعی. با او به‌ندرت حوصله سر می‌رود. او نیاز دارد دیده و شنیده شود، و کسی که جرئت کند به عمق هم برود.',
  4=>'{navn} مسیر زندگی ۴ دارد – زمینی، وفادار و سازنده‌ی چیزهای ماندگار. او محبت را با عمل نشان می‌دهد. سر قولت بمان تا اعتماد سریع رشد کند.',
  5=>'{navn} مسیر زندگی ۵ دارد – آزاد، کنجکاو و همیشه در راه. با او زندگی حرکت می‌شود. نخواه نگهش داری؛ بهتر است دعوتش کنی همراهت شود.',
  6=>'{navn} مسیر زندگی ۶ دارد – مراقب و خانه‌دوست، با قلبی بزرگ برای مسئولیت. او زیاد می‌بخشد. نشان بده تو هم می‌توانی از او مراقبت کنی.',
  7=>'{navn} مسیر زندگی ۷ دارد – اهل تأمل، جست‌وجوگر و دوستدار سکوت. او آرام اما عمیق باز می‌شود. به او زمان بده و پرسش‌هایی بپرس که به زیر سطح می‌روند.',
  8=>'{navn} مسیر زندگی ۸ دارد – هدفمند و اهل عمل. او برابری می‌خواهد، نه تماشاگر. به جاه‌طلبی‌هایش احترام بگذار و جاه‌طلبی‌های خودت را هم نشان بده.',
  9=>'{navn} مسیر زندگی ۹ دارد – سخاوتمند، رمانتیک و آرمان‌گرا. او تصویر بزرگ را می‌بیند و به خیلی‌ها اهمیت می‌دهد. کمکش کن از خودش هم مراقبت کند.'],
 'o_soul' => [1=>'دیده شدن همان‌طور که هست و حق انتخاب', 2=>'نزدیکی، لطافت و کسی که گوش بدهد', 3=>'شادی، بازی و کسی برای خندیدن', 4=>'پیش‌بینی‌پذیری و رابطه‌ای قابل‌اعتماد', 5=>'آزادی و کسی که همراه ماجرا شود', 6=>'خانه‌ای امن – و محبتی که برگردد', 7=>'زمانی برای خودش و گفت‌وگوی عمیق', 8=>'آدم‌هایی که روی پای خودشان بایستند', 9=>'معنا، و رابطه‌ای که جا برای دنیا داشته باشد'],
 'o_expr' => [1=>'رک، شجاع و روشن', 2=>'شنونده، نرم و اهل همکاری', 3=>'جذاب، خلاق و خوش‌صحبت', 4=>'قابل‌اعتماد، دقیق و آرام', 5=>'کنجکاو، بامزه و سرشار از زندگی', 6=>'گرم، مسئول و حامی', 7=>'رازآلود، دانا و اهل تأمل', 8=>'مطمئن، کارآمد و کاریزماتیک', 9=>'سخاوتمند، رمانتیک و بلندنظر'],
 'o_about' => '{life} در درون، {navn} به این نیاز دارد: {soul}. احتمالاً او را این‌طور تجربه می‌کنی: {expr}.',
 'y_you' => [1=>'دلت می‌خواهد چیزی تازه شروع کنی و خودت تصمیم بگیری', 2=>'حساس‌تر می‌شوی و دنبال نزدیکی و همکاری هستی', 3=>'می‌خواهی بیرون بروی، خودت را بیان کنی و آدم‌ها را ببینی', 4=>'درگیر ساختن، سامان دادن و سر جا گذاشتن کارهایی', 5=>'به حرکت، تغییر و هوای تازه نیاز داری', 6=>'خانه، مسئولیت و رابطه‌های نزدیک تو را به خود می‌کشند', 7=>'کمی به درون می‌روی و برای فکر کردن به آرامش نیاز داری', 8=>'کار، پول و نتیجه جای زیادی می‌گیرند', 9=>'فصلی را می‌بندی و برای چیزی تازه جا باز می‌کنی'],
 'y_other' => [1=>'او دلش می‌خواهد چیزی تازه شروع کند و خودش انتخاب کند', 2=>'او نرم‌تر می‌شود و دنبال نزدیکی است', 3=>'او می‌خواهد بیرون برود، خودش را بیان کند و اجتماعی باشد', 4=>'او می‌سازد، سامان می‌دهد و برنامه می‌ریزد', 5=>'او به تغییر و آزادی نیاز دارد', 6=>'خانه و مسئولیت بخش بزرگی از سال او را پر می‌کند', 7=>'او به درون می‌رود و به آرامش نیاز دارد', 8=>'او درگیر کار و نتیجه است', 9=>'او چیزی را تمام می‌کند و برای مرحله بعد آماده می‌شود'],
 'y_pair' => 'تو در سال {a} هستی: {you}. {navn} در سال {b} است: {other}. {link}',
 'y_link' => [
  95=>['هم‌زمان در یک ارتعاش هستید و فهمیدن هم می‌تواند به‌طرز غیرمعمولی آسان باشد. از این باد موافق برای چیزی که با هم می‌سازید استفاده کنید – اما مراقب باشید نقطه‌های کور مشترک را تقویت نکنید.', 'وقتی دو نفر سال شخصی یکسانی دارند، اغلب هم‌زمان از پرسش‌های یکسانی عبور می‌کنند. بلند درباره‌شان حرف بزنید؛ نزدیکی همان‌جا رشد می‌کند.', 'عدد یکسان، موضوع یکسان. آرامش و آشنایی می‌آورد، اما وسوسه‌ی بدیهی گرفتن همدیگر را هم. آنچه را در دیگری می‌بینی به زبان بیاور.', 'امسال هم‌قدم هستید. این یک هدیه است – و دعوتی به این پرسش: می‌خواهیم این هم‌نوایی را برای چه به کار ببریم؟', 'وقتی هر دو یک چیز را حس می‌کنید، تأیید کردن هم آسان است. جرئت مخالفت هم داشته باشید؛ هم‌نوایی را زنده نگه می‌دارد.'],
  85=>['سال‌های شما از یک خانواده‌ی عددی‌اند. آن را متفاوت نشان می‌دهید، اما چیزی خویشاوند شما را می‌راند، و این کمک می‌کند به هم فضا بدهید بی‌آنکه ارتباط را از دست بدهید.', 'این‌ها سال‌هایی خویشاوندند. یکی آشکار نشانش می‌دهد و دیگری آرام‌تر – اما به یک سو می‌کشید. سال خوبی برای یک برنامه‌ی مشترک.', 'میان سال‌های شما خویشاوندی طبیعی هست. اغلب حس می‌کنید دیگری بی‌توضیح طولانی می‌فهمد.', 'امسال به یک زبان حرف می‌زنید، فقط با لهجه‌های متفاوت. گوش بده دیگری واقعاً چه می‌گوید.', 'سال‌های خویشاوند اغلب فهمی آرام می‌آورند. از آن برای تصمیمی استفاده کنید که مدتی است عقب انداخته‌اید.'],
  78=>['سال‌هایتان همدیگر را کامل می‌کنند: آنچه یکی الان کم دارد، دیگری بیشتر دارد. اگر بگذارید هر کدام آنچه را بهتر بلد است بیاورد، سال خوبی می‌شود.', 'ترکیبی مکمل. سعی نکنید شبیه هم شوید – بگذارید تفاوت کارش را بکند، و از آنچه دیگری حمل می‌کند قدردانی کنید.', 'کمی به سوهای متفاوت می‌کشید، اما به شکلی که تعادل می‌سازد. یکی سرعت می‌دهد و دیگری ریشه.', 'جایی که یکی قوی است، دیگری می‌تواند استراحت کند. امسال بلند بگو چه چیزی را در دیگری دوست داری.', 'سالی است که می‌توانید از هم یاد بگیرید. از موضوع سال دیگری چه می‌توانی با خودت ببری؟'],
  60=>['سال‌هایتان کنار هم می‌ایستند بی‌آنکه به‌طور خاص به هم نزدیک یا از هم دور کنند. این آزادی می‌دهد، و همچنین مسئولیت ساختن بخش مشترک را.', 'نه باد موافق قوی، نه باد مخالف. نزدیکی از کارهایی می‌آید که انتخاب می‌کنید با هم انجام دهید، نه فقط از عددها.', 'سالی خنثی میان شما. زیاد از هم بپرسید: الان از من به چه نیاز داری؟', 'امسال عددها شما را به حال خودتان می‌گذارند. یعنی حال‌وهوا را خودتان تعیین می‌کنید.', 'سالی که هر کدام سرگرم کار خودتان هستید. زمانی ثابت فقط برای خودتان بگذارید تا از کنار هم رد نشوید.'],
  45=>['اینجا ممکن است سرعت‌هایتان به دو سو بکشند. لازم نیست به دعوا برسد، اما باید روشن بگویید به چه نیاز دارید – پیش از آنکه دلخوری به جایتان بگوید.', 'عددشناسی این را جفت اصطکاکی می‌نامد. اصطکاک خطا نیست؛ اغلب همان‌جاست که بیشترین شناخت از هم به دست می‌آید. زود توافق کنید چطور بی‌آنکه کناره بگیرید استراحت کنید.', 'سالی که صبر را می‌آزماید. آنچه در دیگری آزارت می‌دهد، شاید نشانت دهد خودت به چه بیشتر یا کمتر نیاز داری.', 'امسال سرعت‌ها متفاوت است: یکی یک راه می‌خواهد و دیگری راهی دیگر. به جای «چرا این‌طوری می‌کنی؟» بپرس «به چه نیاز داری؟».', 'اصطکاک اگر درست به کار برود می‌تواند گرما بسازد. در دوره‌هایی که اوضاع ناهموار است با هم سخاوتمند باشید.']],
 'rel' => [
  1=>'عدد مشترک ۱ زوجی می‌سازد که با هم چیزها را آغاز می‌کنند. می‌توانید موتور هم باشید – پروژه‌ها، جاها و فصل‌های تازه. کار شما این است که آن را ابتکاری مشترک کنید، نه دو مسیر موازی.',
  2=>'عدد مشترک ۲ عدد خود همراهی است. قدرت در هماهنگی آرام است: گوش دادن، صبر کردن و با هم راه‌حل پیدا کردن. مراقب باشید آن‌قدر از اختلاف دوری نکنید که ناگفته‌ها سنگین شوند.',
  3=>'عدد مشترک ۳ زوجی بازیگوش و اجتماعی می‌سازد. شوخ‌طبعی، خلاقیت و دوستان دورتان چسب این رابطه‌اند. یادتان باشد از سختی‌ها هم حرف بزنید – نه فقط از چیزهای شاد.',
  4=>'عدد مشترک ۴ می‌سازد: خانه، روال و وفاداری‌ای که در زمان دوام می‌آورد. چنین پیوندی اغلب سال به سال محکم‌تر می‌شود، به شرط آنکه نظم، خودجوشی را خفه نکند.',
  5=>'عدد مشترک ۵ زوجی ماجراجو می‌سازد: سفر، تغییر و آزادی. زنده است – و لازم است توافق کنید چه چیزی امن است تا آزادی به فاصله تبدیل نشود.',
  6=>'عدد مشترک ۶ درباره‌ی خانه، مراقبت و مسئولیت است – پیوندی که دیگران دوست دارند دورش جمع شوند. مسئولیت را تقسیم کنید تا هیچ‌کدام همه‌چیز را به دوش نکشید.',
  7=>'عدد مشترک ۷ عدد هم‌جان‌هاست: عمق، گفت‌وگو و احترام به فضای هم. لازم نیست همیشه کنار هم باشید تا نزدیک باشید.',
  8=>'عدد مشترک ۸ زوجی پرقدرت با هدف‌های مشترک می‌سازد. یادتان باشد این پیوند پروژه‌ای برای تحویل دادن نیست – برای زیستن هم هست.',
  9=>'عدد مشترک ۹ پیوندی سخاوتمند و آرمان‌گرا می‌سازد که چیزی بزرگ‌تر از خودش می‌خواهد. می‌توانید برای دیگران خیلی مهم باشید. از آنچه میان شما دو نفر است هم مراقبت کنید.'],
 'chat' => ['سلام، چه خوب که نوشتی! دیدم عدد مشترک ما {rel} است – {theme}. خودت را در آن می‌بینی؟', 'مسیر زندگی من {lp} است و راستش به {soul} نیاز دارم. برای تو چه چیزی مهم‌تر است؟', 'موتور می‌گوید {pct}٪، اما من بیشتر کنجکاو خودت هستم، فراتر از عددها. یکشنبه‌ها بیشتر دوست داری چه کنی؟', 'الان در سال {py} هستم و حسش می‌کنم: {year}. سال تو چطور است؟', 'طبق عددها {month} قوی‌ترین ماه ماست. آن موقع برنامه‌ای بچینیم؟ 😊', 'خواندم که مسیر زندگی {olp} یعنی {type}. درباره‌ی تو درست است؟', 'خیلی خوب بود. یک روز در {city} قهوه بخوریم؟'],
 'c_soul' => [1=>'جایی برای خودم بودن', 2=>'نزدیکی و کسی که گوش بدهد', 3=>'کسی برای خندیدن', 4=>'کسی که بتوانم کامل به او اعتماد کنم', 5=>'آزادی و کمی ماجرا', 6=>'تعلق داشتن به جایی', 7=>'زمانی برای خودم و گفت‌وگوهای واقعی', 8=>'برابری', 9=>'اینکه آنچه داریم معنا داشته باشد'],
 'c_year' => [1=>'دلم می‌خواهد چیزی تازه شروع کنم', 2=>'همه‌چیز کمی آهسته‌تر است و دنبال نزدیکی بیشترم', 3=>'می‌خواهم بیرون بروم و آدم‌ها را ببینم', 4=>'دارم مرتب می‌کنم و می‌سازم', 5=>'همه‌چیز در حرکت است', 6=>'خانه و نزدیکانم جای زیادی می‌گیرند', 7=>'بیشتر از همیشه به آرامش نیاز دارم', 8=>'کار خیلی وقت می‌گیرد', 9=>'دارم فصلی را می‌بندم'],
],
];

function tx(string $key) { global $LANG; return TX[$LANG][$key] ?? TX['no'][$key]; }
function t_pron(array $u): array {
    global $LANG;
    if ($LANG === 'en') return match ($u['gender']) { 'woman' => ['her', 'her'], 'man' => ['him', 'his'], default => ['them', 'their'] };
    return match ($u['gender']) { 'woman' => ['hun', 'henne', 'hennes'], 'man' => ['han', 'ham', 'hans'], default => ['hen', 'hen', 'hens'] };
}
function t_fill(string $s, array $u): string {
    global $LANG;
    $p = t_pron($u);
    $map = ['{navn}'=>$u['alias']];
    if ($LANG === 'en') $map += ['{them}'=>$p[0], '{their}'=>$p[1]];
    elseif ($LANG === 'no') $map += ['{Hun}'=>mb_strtoupper(mb_substr($p[0], 0, 1)) . mb_substr($p[0], 1), '{hun}'=>$p[0], '{henne}'=>$p[1], '{hennes}'=>$p[2]];
    return strtr($s, $map);
}
function t_label(int $pct): string { $l = tx('label'); return $l[$pct >= 90 ? 0 : ($pct >= 75 ? 1 : ($pct >= 60 ? 2 : ($pct >= 40 ? 3 : 4)))]; }
/** Paragraphs about the reader; the last one is the closing question. */
function t_about_me(array $p): array {
    $a = tx('about');
    $out = [tx('life')[$p['life']['root']] . (isset(tx('master')[$p['life']['kept']]) ? ' ' . tx('master')[$p['life']['kept']] : '')];
    $out[] = strtr($a[0], ['{soul}'=>$p['soul']['label'], '{soultext}'=>tx('soul')[$p['soul']['root']], '{expr}'=>$p['expression']['label'], '{exprtext}'=>tx('expr')[$p['expression']['root']]]);
    $out[] = strtr($a[1], ['{mat}'=>$p['maturity']['label'], '{mattext}'=>tx('mat')[$p['maturity']['root']]]);
    $out[] = strtr($a[2], ['{y}'=>date('Y'), '{py}'=>$p['personal_year'], '{yeartext}'=>tx('year')[$p['personal_year']]]);
    $out[] = tx('question')[$p['life']['root']];
    return $out;
}
function t_about_other(array $p, array $u): string {
    return t_fill(strtr(tx('o_about'), ['{life}'=>tx('o_life')[$p['life']['root']], '{soul}'=>tx('o_soul')[$p['soul']['root']], '{expr}'=>tx('o_expr')[$p['expression']['root']]]), $u);
}
function t_year_pair(int $a, int $b, int $score, array $other, int $year): string {
    $v = tx('y_link')[$score];
    return t_fill(strtr(tx('y_pair'), ['{a}'=>$a, '{b}'=>$b, '{you}'=>tx('y_you')[$a], '{other}'=>tx('y_other')[$b], '{link}'=>$v[$year % count($v)]]), $other);
}
